programs.haiku:
"""Causing and letting verbs push this unit negative; the person they act on pushes it up.

Layer 15, MLP down_proj, hidden unit 1667. The unit is strongly negative on a verb that sets
up "someone is let, allowed, made, helped or asked to do something": let, allow, enable,
ensure, ask, want, encourage, make, have, help, tell, and 让/讓/使/令 (Chinese), чтобы, dass,
aby. Those verbs are most negative when they are infinitives (after "to" or a modal, e.g.
"to let", "to have"). The determiner after such a verb (the, a, their) is a little negative,
and "that" in "so that" is more negative. The unit is positive on the person such a verb
acts on (made ME, told US, help THEM), and on the "to" after that person (asked US to).

The values are group means, fitted by least squares on 16k training rows. Token identity and
these rules explain about 5% of the variance; most of the rest sits in context this
program does not model.
"""

READS = ()

# Verbs of making, letting, permitting and enabling: the strongest negatives.
LETTING_STRONG = {"letting", "allowing", "enabling", "ensuring", "让", "讓", "使", "令"}
# Verbs of letting, allowing, asking, wanting and encouraging: moderate negatives.
LETTING = {"let", "lets", "allow", "allows", "allowed", "enable", "enables", "permit",
           "ensure", "ensures", "ask", "asks", "asked", "asking", "want", "wants", "wanted",
           "encourage", "encourages", "encouraged", "helping", "having", "facilitate",
           "чтобы", "dass", "daß", "aby"}
# Verbs of having, making, helping, getting and telling: weak negatives.
CAUSING = {"have", "had", "make", "made", "making", "makes", "help", "helps", "helped",
           "get", "give", "provide", "tell", "told", "tells", "need", "able", "sure",
           "cause", "causes", "causing", "send"}
GOVERNING = LETTING_STRONG | LETTING | CAUSING | {"so"}
INFINITIVE = {"to", "will", "would", "can", "could", "should", "must", "may", "might"}
PERSONS = {"me", "us", "you", "them", "him", "her"}
DETERMINERS = {"the", "a", "an", "this", "that", "his", "their", "its", "my", "your", "our",
               "it"}


def _word(prefix, back):
    """The token `back` places before the newest one, or "" across a document break."""
    i = len(prefix.token_strings) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = _word(prefix, 1)
    prev2 = _word(prefix, 2)
    value = -0.07
    if cur in LETTING_STRONG:
        value += -4.7
    elif cur in LETTING:
        value += -1.8 * (2.0 if prev in INFINITIVE else 1.0)
    elif cur in CAUSING:
        value += -0.85 * (2.0 if prev in INFINITIVE else 1.0)
    if cur in PERSONS and prev in GOVERNING:
        value += 0.8
    if cur in DETERMINERS and prev in GOVERNING:
        value += -0.75
    if cur == "that" and prev in {"so", "such"}:
        value += -1.8
    if cur == "to" and prev in PERSONS and prev2 in GOVERNING:
        value += 1.2
    return carry, float(value)

"""Layer 15 MLP down-projection component 1678, predicted from the kind of the current token.

The component's activation is a small, diffuse signal. Its average depends a little on
what kind of text piece the current token is, measured on training text:
capitalised words and plain words sit below zero, word-initial spaces sit near zero.
This program predicts each kind's average. It explains only a sliver of the variance;
most of the activation is not tied to any token or position concept.
"""

READS = ()

# average activation per kind of token (training text)
MEANS = {
    "partial": -0.023,  # half of a multi-byte character
    "newline": -0.036,
    "space": -0.023,
    "cjk": -0.016,
    "digit": -0.019,
    "space_Cap": -0.028,  # space then capital letter
    "space_word": -0.006,  # space then lower-case word
    "Cap": -0.073,  # capital letter with no space before
    "word": -0.046,  # lower-case word with no space before
    "punct": -0.017,
    "other": -0.043,
}


def kind(s):
    if "�" in s:
        return "partial"
    if s.isspace():
        return "newline" if "\n" in s else "space"
    if any("一" <= c <= "鿿" for c in s):
        return "cjk"
    if s.strip().isdigit():
        return "digit"
    if s[:1] == " ":
        return "space_Cap" if s[1:2].isupper() else "space_word"
    if s[:1].isupper():
        return "Cap"
    if s[:1].isalpha():
        return "word"
    if not any(c.isalnum() for c in s):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    return carry, MEANS[kind(prefix.token_strings[-1])]

"""Layer 15 MLP down_proj, component 1695 of Qwen3-1.7B.

What it does: a diffuse, mostly noisy feature. Its activation is about 0 on average
(mean 0.08, std 0.9), and nothing simple explains most of its swing. The one clear pattern is
in the sign on the token just read:
  - it leans negative at line and paragraph breaks ('.\\n', '\\n\\n', ' {\\n') and on code
    symbols ('//', '{', '}'), where its strongest negative values (below -4) cluster;
  - it leans slightly positive on spaces and indentation, digits and words.
The program predicts the average activation of each of these token classes.
"""

READS = ()

CODE_SYMBOLS = {"//", "{", "}", "(", ")", "[", "]", ";"}
PUNCTUATION = {".", ",", ":", "!", "?", "-"}

# Average activation per class, measured on 131k training tokens.
MEAN = {"break_end": -0.45, "break": -0.29, "code": -0.35, "punct": -0.03,
        "space": 0.14, "digit": 0.12, "word": 0.07}


def token_class(text):
    """The class of one decoded token."""
    if "\n" in text:
        return "break_end" if text.rstrip(" ").endswith((".", ":", "{")) else "break"
    stripped = text.strip()
    if stripped == "":
        return "space"
    if stripped in CODE_SYMBOLS:
        return "code"
    if stripped in PUNCTUATION:
        return "punct"
    if stripped.isdigit():
        return "digit"
    return "word"


def step(carry, prefix, upstream):
    """This token's predicted activation, from the class of the token just read."""
    return carry, MEAN[token_class(prefix.token_strings[-1])]

"""Explainer for layers.15.mlp.down_proj component 1708.

What it does: a weak, diffuse signal. Its activation has std 0.29 over the eval rows,
but no concept accounts for much of it. The current token explains only about 1%
of the variance, spread over tens of thousands of token types, and context adds the
rest in ways no short rule captures. This program predicts a few small averages that
do have a reading:
  - forms of the verb "to be" (is, are, be, was, were, been) sit below zero, about -0.10;
  - forms of "to have" (have, has, had) sit slightly above zero, about +0.07;
  - the chat role names "user" and "assistant" sit higher, about +0.2;
  - otherwise by character class: digits and punctuation slightly negative, ordinary
    words slightly negative, Han characters near zero.
The predictions are small, so this component's output barely moves the model.
"""
import regex

READS = ()

BE_FORMS = {"is", "are", "be", "was", "were", "been", "being"}
HAVE_FORMS = {"have", "has", "had"}
ROLE_NAMES = {"user", "assistant"}

# Mean activation per character class, measured on training rows.
CLASS_MEAN = {
    "digit": -0.037,
    "punct": -0.025,
    "newline": -0.026,
    "space": -0.014,
    "word": -0.012,
    "han": -0.002,
    "other": 0.0,
}


def char_class(text):
    if regex.fullmatch(r"\s*[0-9]+", text):
        return "digit"
    if regex.fullmatch(r"\s*\p{Han}+", text):
        return "han"
    if regex.fullmatch(r"\s*[\p{L}]+", text):
        return "word"
    if regex.fullmatch(r"\s+", text):
        return "space"
    if "\n" in text:
        return "newline"
    if regex.fullmatch(r"\s*[\p{P}\p{S}]+", text):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    if word in BE_FORMS:
        return carry, -0.10
    if word in HAVE_FORMS:
        return carry, 0.07
    if word in ROLE_NAMES:
        return carry, 0.20
    return carry, CLASS_MEAN[char_class(text)]
